// Endpoints: autogenerated (endpoints/auto_<table>.json) and custom (endpoints/<table>.json),
// all in one grid (the Source column says which). Views: #/endpoints (the grid),
// #/endpoints/new, #/endpoints/edit/<file>/<name> and #/endpoints/try/<file>/<name>.
import { api, esc, attempt, toast, needsConfirm, editing, link, method, iconButton, callApi, statusClass, json, session, studentApi } from "../ui.js";
import { dataTable } from "../components/table.js";

const SOURCES = { auto: "Autogenerated", custom: "Custom" };

export function crumbs(params) {
  const [view, file, name] = params;
  const base = [{ label: "Endpoints", href: "#/endpoints" }];
  if (view === "edit") return [...base, { label: `Edit ${file}/${name}` }];
  if (view === "new") return [...base, { label: "New" }];
  if (view === "try") return [...base, { label: `Try ${file}/${name}` }];
  return [{ label: "Endpoints" }];
}

export function parent(params) {
  const [view] = params;
  return view === "edit" || view === "new" || view === "try" ? "#/endpoints" : null;
}

export async function render(main, app, params) {
  const [view, file, name] = params;
  if (view === "edit") return editPage(main, app, file, name);
  if (view === "new") return editPage(main, app, null, null);
  if (view === "try") return tryPage(main, app, file, name);
  return listPage(main, app);
}

async function load() {
  return attempt(() => api("/endpoints"));
}

function access(e) {
  if (!(e.auth_required || e.owner)) return "Public";
  const roles = e.allowed_roles.includes("*") ? "" : `, roles ${e.allowed_roles.join(", ")}`;
  return `Authentication required${roles}${e.owner ? `, owner ${e.owner}` : ""}`;
}

const anyRole = (e) => !e.allowed_roles?.length || e.allowed_roles.includes("*");

///////////////////////////////////////////////////////////////////////////////
// The grid. Who can call each endpoint is changed in the grid itself, as in silence-dev4, and
// saved at once: Auth (a switch), Roles (a combo) and Owner (the column with the id of the
// owner; not with roles). Changing an autogenerated endpoint moves it to custom (where its SQL
// can be edited); deleting a custom one serves the autogenerated one again, if there is one.
///////////////////////////////////////////////////////////////////////////////

// What to do when a list of roles closes (the one of the grid on screen)
let rolesClosed = null;
document.addEventListener("hidden", (event) => {
  const drop = event.target.closest?.(".sa-roles__drop");
  if (drop && rolesClosed) rolesClosed(drop);
}, true);

async function listPage(main, app) {
  rolesClosed = null;
  document.querySelectorAll("body > .sa-roles__drop").forEach((d) => d.remove());  // Of the previous grid
  if (app.status.database.error) {
    main.innerHTML = `<h1>Endpoints</h1><div class="uk-alert uk-alert-warning">Connect to the database first, in <a href="#/database/connection">Database</a>.</div>`;
    return;
  }
  const linked = app.status.auth.linked;
  const [data, schema, users] = await Promise.all([load(), attempt(() => api("/schema")),
    linked && app.status.auth.role ? api("/users").catch(() => null) : null]);
  if (!data || !schema) return;
  const all = data.endpoints;
  const rows = all;
  const count = (s) => all.filter((e) => e.source === s).length;
  const relationOf = (table) => schema.relations.find((r) => r.name.toLowerCase() === table.toLowerCase());
  // The roles offered: those of the users plus those already used by the endpoints
  const knownRoles = [...new Set([...(users?.users ?? []).map((u) => u.role),
    ...all.flatMap((e) => (anyRole(e) ? [] : e.allowed_roles))].filter((r) => r !== null && r !== undefined && r !== "").map(String))].sort();

  main.innerHTML = `
    <h1>Endpoints</h1>
    ${data.errors.length ? `<div class="uk-alert uk-alert-danger"><strong>Endpoints not loaded</strong>
      <ul>${data.errors.map((e) => `<li>${esc(e)}</li>`).join("")}</ul></div>` : ""}
    <div class="sa-toolbar">
      <button class="uk-button uk-button-primary" type="button" id="generate">Generate from the database</button>
      <a class="uk-button uk-button-default" href="#/endpoints/new">New custom endpoint</a>
      <span class="sa-toolbar__spacer"></span>
      <span class="uk-text-muted sa-small">${count("auto")} autogenerated · ${count("custom")} custom</span>
    </div>
    <p class="uk-text-muted sa-small">The autogenerated endpoints are public. Changing the access of one makes it custom (its
      SQL can be edited then); deleting a custom one brings back the autogenerated one, if there is one. A custom endpoint
      with the method and route of an autogenerated one replaces it.</p>
    ${linked ? "" : `<p class="uk-text-muted sa-small">To ask for authentication, roles or owners, link the users table first, in
      <a href="#/database/auth">Database</a>.</p>`}
    <div id="grid"></div>`;

  const off = linked ? "" : "disabled";
  const authCell = (e) => `<label class="sa-switch" title="${linked ? "Requires authentication" : "Link the users table first"}">
      <input type="checkbox" data-field="auth" ${e.auth_required || e.owner || !anyRole(e) ? "checked" : ""} ${off}
        aria-label="${esc(e.method)} ${esc(e.route)} requires authentication"><span class="sa-switch__slider"></span></label>`;
  const rolesCell = (e) => {
    const chosen = anyRole(e) ? [] : e.allowed_roles;
    const blockedBy = e.owner && anyRole(e) ? "An endpoint with an owner is for any role: remove the owner to choose roles" : "";
    const options = [...new Set([...knownRoles, ...chosen])].sort();
    return `<div class="sa-roles">
      <button class="uk-button uk-button-default uk-button-small sa-roles__button" type="button" ${off || (blockedBy ? "disabled" : "")}
        title="${esc(blockedBy || "Allowed roles")}">${chosen.length ? esc(chosen.join(", ")) : `<span class="uk-text-muted">any</span>`}
        <span uk-icon="icon: triangle-down; ratio: .7"></span></button>
      ${off || blockedBy ? "" : `<div class="sa-roles__drop" data-row="${rows.indexOf(e)}" uk-dropdown="mode: click; pos: bottom-left; animation: false; flip: false; shift: false; container: body">
        ${options.length ? options.map((r) => `<label class="sa-roles__option"><input class="uk-checkbox" type="checkbox" data-role="${esc(r)}"
          ${chosen.includes(r) ? "checked" : ""}> ${esc(r)}</label>`).join("") : `<p class="uk-text-muted sa-small">No roles yet</p>`}
        <input class="uk-input uk-form-small" data-role-new placeholder="Another role" aria-label="Another role">
        <p class="sa-small uk-text-muted uk-margin-small-top uk-margin-remove-bottom">Saved when this list closes. None: any role.</p>
      </div>`}
      ${e.owner && !anyRole(e) ? `<span class="uk-text-warning" title="Owner and roles together: choose one of them">⚠</span>` : ""}
    </div>`;
  };
  const ownerCell = (e) => {
    if (e.method === "GET") return `<span class="uk-text-muted" title="An owner only restricts POST, PUT and DELETE">—</span>`;
    const cols = relationOf(e.table)?.columns.map((c) => c.name) ?? [];
    const blockedBy = !anyRole(e) && !e.owner ? "An endpoint with roles has no owner: remove the roles to choose one" : "";
    const dis = off || (blockedBy ? "disabled" : "");
    if (!cols.length) {
      return `<input class="uk-input uk-form-small sa-owner" data-field="owner" value="${esc(e.owner ?? "")}" placeholder="column" ${dis}
        title="${esc(blockedBy || "The column with the id of the owner")}" aria-label="Owner column">`;
    }
    return `<select class="uk-select uk-form-small sa-owner" data-field="owner" ${dis} title="${esc(blockedBy || "The column with the id of the owner")}"
        aria-label="Owner column"><option value="">—</option>${[...new Set([...cols, ...(e.owner ? [e.owner] : [])])].map((c) =>
        `<option ${c === e.owner ? "selected" : ""}>${esc(c)}</option>`).join("")}</select>`;
  };

  const columns = [
    // The actions go first, so that they are always seen however wide the grid is
    { key: "actions", label: "", filter: false, sortable: false, className: "sa-actions", render: (e) =>
      iconButton("play", "Try", { href: link("endpoints", "try", e.file, e.name) }) +
      (e.source === "custom"
        ? iconButton("pencil", "Edit (also its SQL)", { href: link("endpoints", "edit", e.file, e.name) }) +
          iconButton("trash", e.overrides?.length || autoTables.has(e.table.toLowerCase())
            ? "Delete (the autogenerated one is served again, if there is one)" : "Delete", { action: "delete", danger: true })
        : "") },
    { key: "method", label: "Method", filter: "select", render: (e) => method(e.method) },
    { key: "route", label: `Route (${data.apiPrefix})`, value: (e) => e.route, render: (e) =>
        `<span class="sa-route">${esc(e.route)}</span>` +
        (e.overrides?.length ? `<br><span class="sa-small uk-text-primary">Replaces an autogenerated one</span>` : "") +
        (e.warnings.length ? `<br><span class="sa-small uk-text-warning">⚠ ${esc(e.warnings.join("; "))}</span>` : "") },
    { key: "table", label: "Table", filter: "select" },
    { key: "source", label: "Source", filter: "select", value: (e) => e.source,
      render: (e) => `<span class="uk-label sa-label-${e.source} sa-label-small" title="${SOURCES[e.source]}">${e.source}</span>` },
    { key: "auth", label: "Auth", filter: "select", value: (e) => (e.auth_required || e.owner || !anyRole(e) ? "yes" : "no"), render: authCell },
    { key: "roles", label: "Roles", filter: "select", value: (e) => (anyRole(e) ? "any" : e.allowed_roles.join(", ")), render: rolesCell },
    { key: "owner", label: "Owner", filter: "select", value: (e) => e.owner ?? "", render: ownerCell },
  ];
  const autoTables = new Set(schema.relations.map((r) => r.name.toLowerCase()));

  const grid = main.querySelector("#grid");
  dataTable(grid, {
    columns, rows, sort: { key: "route", dir: "asc" },
    emptyHtml: `No endpoints yet. <button class="uk-button uk-button-primary uk-button-small" type="button" data-empty="generate">Generate
      them from the database</button> (one file per table and view, with its CRUD), or write a custom one.`,
    onAction: async (action, e, button) => {
      if (action !== "delete" || !needsConfirm(button, "Delete?")) return;
      if (!await attempt(() => api(`/endpoints/${e.file}/${e.name}`, "DELETE", undefined, data.files[e.file] ?? ""), "Deleted")) return;
      if (autoTables.has(e.table.toLowerCase())) {
        // The autogenerated one of the same method and route is served again (if there is one)
        await api("/endpoints/generate", "POST", { tables: [relationOf(e.table).name] }).catch(() => null);
      }
      await app.refreshStatus();
      listPage(main, app);
    },
  });

  const rowOf = (el) => rows[Number(el.closest("tr[data-row]").dataset.row)];

  // Auth and Owner: saved when they change
  grid.addEventListener("change", (event) => {
    const field = event.target.closest("[data-field]");
    if (!field || !field.closest("tbody")) return;
    const e = rowOf(field);
    if (field.dataset.field === "auth") {
      save(e, field.checked ? { auth_required: true } : { auth_required: false, allowed_roles: ["*"], owner: null });
    }
    if (field.dataset.field === "owner") {
      const owner = field.value.trim();
      save(e, owner ? { owner, auth_required: true, allowed_roles: ["*"] } : { owner: null });
    }
  });
  // Roles: saved when their list closes, if they changed. UIkit moves the lists to the body (so
  // that the grid's scroll does not cut them), so they are caught there.
  rolesClosed = (drop) => {
    const e = rows[Number(drop.dataset.row)];
    if (!e) return;
    const roles = [...drop.querySelectorAll("[data-role]:checked")].map((c) => c.dataset.role);
    const extra = drop.querySelector("[data-role-new]").value.trim();
    if (extra && !roles.includes(extra)) roles.push(extra);
    const before = anyRole(e) ? [] : e.allowed_roles;
    if (roles.join(",") === before.join(",")) return;
    save(e, roles.length ? { allowed_roles: roles, auth_required: true, owner: null } : { allowed_roles: ["*"] });
  };

  async function save(e, changes) {
    let file = e.file;
    let name = e.name;
    if (e.source === "auto") {
      const moved = await attempt(() => api(`/endpoints/${e.file}/${e.name}/customize`, "POST"));
      if (!moved) return listPage(main, app);
      ({ file, name } = moved);
    }
    const entry = await attempt(() => api(`/endpoints/${file}/${name}`));
    if (!entry) return listPage(main, app);
    const def = { ...entry.data, ...changes };
    if (!def.owner) delete def.owner;
    await attempt(() => api(`/endpoints/${file}/${name}`, "PUT", def, entry.etag),
      e.source === "auto" ? `${e.method} ${e.route}: saved (now custom)` : `${e.method} ${e.route}: saved`);
    await app.refreshStatus();
    listPage(main, app);
  }

  const generate = main.querySelector("#generate");
  grid.addEventListener("click", (event) => {
    if (event.target.closest('[data-empty="generate"]')) generate.click();
  });
  generate?.addEventListener("click", async () => {
    if (all.length && !needsConfirm(generate, "Overwrite the auto_ files?")) return;
    const res = await attempt(() => api("/endpoints/generate", "POST", {}));
    if (res) {
      toast(`${res.tables.reduce((n, t) => n + t.generated.length, 0)} endpoints generated for ${res.tables.length} tables and views`, "success");
      await app.refreshStatus();
      listPage(main, app);
    }
  });
}

///////////////////////////////////////////////////////////////////////////////
// Create or edit a custom endpoint
///////////////////////////////////////////////////////////////////////////////

async function editPage(main, app, file, name) {
  const data = await load();
  if (!data) return;
  const ep = file ? data.endpoints.find((e) => e.file === file && e.name === name) : null;
  if (file && !ep) {
    main.innerHTML = `<div class="uk-alert uk-alert-danger">There is no endpoint ${esc(name)} in ${esc(file)}.json.</div>`;
    return;
  }
  const e = ep ?? { name: "", file: "", method: "GET", route: "/", sql: "SELECT * FROM ", auth_required: false,
    allowed_roles: ["*"], description: "", request_body_params: [], owner: "" };
  const tables = [...new Set(data.endpoints.map((x) => x.table))].sort();

  main.innerHTML = `
    <h1>${ep ? `Edit ${esc(ep.method)} ${esc(data.apiPrefix + ep.route)}` : "New custom endpoint"}</h1>
    <form id="edit-form" class="sa-form sa-form--wide">
      <div class="sa-field"><label class="uk-form-label" for="ep-name">Name</label>
        <input class="uk-input" id="ep-name" name="name" value="${esc(e.name)}" required pattern="\\w+"></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-file">File (endpoints/….json)</label>
        <input class="uk-input" id="ep-file" name="file" value="${esc(e.file)}" required pattern="[\\w\\-]+" list="ep-files"
          placeholder="its table, e.g. ${esc(tables[0] ?? "photos")}">
        <datalist id="ep-files">${tables.map((t) => `<option value="${esc(t)}">`).join("")}</datalist></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-method">Method</label>
        <select class="uk-select" id="ep-method" name="method">
          ${["GET", "POST", "PUT", "DELETE"].map((m) => `<option ${m === e.method ? "selected" : ""}>${m}</option>`).join("")}</select></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-route">Route (after ${esc(data.apiPrefix)}; params with $)</label>
        <input class="uk-input" id="ep-route" name="route" value="${esc(e.route)}" required></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-sql">SQL ($params from the route, the body and $loggedId)</label>
        <textarea class="uk-textarea sa-code" id="ep-sql" name="sql" required>${esc(e.sql)}</textarea></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-body">Body params (comma-separated, for POST and PUT)</label>
        <input class="uk-input" id="ep-body" name="request_body_params" value="${esc((e.request_body_params || []).join(", "))}"></div>
      <div class="sa-field"><label><input class="uk-checkbox" type="checkbox" name="auth_required" ${e.auth_required ? "checked" : ""}> Requires authentication</label></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-roles">Allowed roles (* any)</label>
        <input class="uk-input" id="ep-roles" name="allowed_roles" value="${esc((e.allowed_roles || ["*"]).join(", "))}"></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-owner">Owner column (optional)</label>
        <input class="uk-input" id="ep-owner" name="owner" value="${esc(e.owner || "")}"
          title="Only the user whose id is in this column can modify or delete the row; in a POST, it is set to the logged user"></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-desc">Description</label>
        <input class="uk-input" id="ep-desc" name="description" value="${esc(e.description)}"></div>
      <div class="sa-toolbar sa-span">
        <button class="uk-button uk-button-primary" type="submit">Save</button>
        <a class="uk-button uk-button-default" href="#/endpoints">Cancel</a>
      </div>
    </form>`;

  const form = main.querySelector("#edit-form");
  form.addEventListener("input", () => editing(main, true));
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const v = Object.fromEntries(new FormData(form));
    const list = (s) => (s || "").split(",").map((x) => x.trim()).filter(Boolean);
    const def = { description: v.description, route: v.route, method: v.method, sql: v.sql,
      auth_required: form.querySelector("[name=auth_required]").checked,
      allowed_roles: list(v.allowed_roles).length ? list(v.allowed_roles) : ["*"] };
    if (list(v.request_body_params).length) def.request_body_params = list(v.request_body_params);
    if (v.owner.trim()) def.owner = v.owner.trim();
    if (def.owner && !def.allowed_roles.includes("*")) {
      toast("An endpoint has an owner or roles, not both: an owner is for any role", "error");
      return;
    }
    if (def.owner || !def.allowed_roles.includes("*")) def.auth_required = true;
    const saved = await attempt(() => api(`/endpoints/${encodeURIComponent(v.file)}/${encodeURIComponent(v.name)}`, "PUT",
      def, data.files[v.file] ?? ""), `Saved in endpoints/${v.file}.json`);
    if (!saved) return;
    if (ep && (ep.name !== v.name || ep.file !== v.file)) {  // Renamed or moved: remove the old one
      const etag = ep.file === v.file ? saved.etag : data.files[ep.file] ?? "";
      await attempt(() => api(`/endpoints/${ep.file}/${ep.name}`, "DELETE", undefined, etag));
    }
    editing(main, false);
    await app.refreshStatus();
    location.hash = "#/endpoints";
  });
}

///////////////////////////////////////////////////////////////////////////////
// Try an endpoint
///////////////////////////////////////////////////////////////////////////////

/** Rows of the endpoint's table, to propose real values: from a GET of the student's API on the
 *  same table without params (e.g., GET /departments), with the session chosen. [] if there is none. */
async function sampleRows(e, endpoints, prefix) {
  const list = endpoints.find((x) => x.method === "GET" && x.table === e.table && !x.route.includes("$"));
  if (!list) return { rows: [], from: null };
  const headers = {};
  const token = session.get()?.token;
  if (token) headers[studentApi.sessionHeader] = token;
  try {
    const response = await fetch(prefix + list.route, { headers });
    const data = await response.json();
    return { rows: Array.isArray(data) ? data.filter((r) => r && typeof r === "object").slice(0, 100) : [], from: list.route };
  } catch {
    return { rows: [], from: list.route };
  }
}

/** The value of a row for a param (same name, ignoring case) */
const valueFor = (row, param) => {
  const key = Object.keys(row).find((k) => k.toLowerCase() === param.toLowerCase());
  return key === undefined ? undefined : row[key];
};

async function tryPage(main, app, file, name) {
  const data = await load();
  if (!data) return;
  const e = data.endpoints.find((x) => x.file === file && x.name === name);
  if (!e) {
    main.innerHTML = `<div class="uk-alert uk-alert-danger">There is no endpoint ${esc(name)} in ${esc(file)}.json.</div>`;
    return;
  }
  editing(main, true);  // Do not re-render (and lose the response) when the files change
  const prefix = data.apiPrefix;
  const params = [...e.route.matchAll(/\$(\w+)/g)].map((m) => m[1]);
  const bodyParams = e.method === "POST" || e.method === "PUT" ? e.request_body_params ?? [] : [];
  const linked = app.status.auth.linked;
  const [users, sample] = await Promise.all([
    linked ? api("/users", "GET", undefined, undefined, { quiet: true }).catch(() => null) : null,
    sampleRows(e, data.endpoints, prefix),
  ]);
  const current = session.get();
  const pwd = linked ? app.status.auth.password?.toLowerCase() : null;
  const label = (r) => Object.values(r).filter((v) => v !== null && typeof v !== "object").slice(0, 3).join(" · ");

  main.innerHTML = `
    <h1>${method(e.method)} <span class="sa-route">${esc(prefix + e.route)}</span></h1>
    <p class="uk-text-muted">${e.description ? `${esc(e.description)} · ` : ""}${esc(access(e))}</p>
    <form id="try-form">
      <div class="sa-form">
        <div class="sa-field"><label class="uk-form-label" for="try-user">As user</label>
          <select class="uk-select" id="try-user" ${users ? "" : "disabled"} title="${linked ? "" : "Link the users table to use sessions"}">
            <option value="">Without a session</option>
            ${(users?.users ?? []).map((u) => `<option value="${esc(u.id)}" ${String(current?.id) === String(u.id) ? "selected" : ""}>
              ${esc(u.identifier)}${u.role ? ` (${esc(u.role)})` : ""}</option>`).join("")}
          </select></div>
        ${sample.rows.length && (params.length || bodyParams.length) ? `<div class="sa-field sa-span"><label class="uk-form-label" for="try-row">Fill with the data of a row
          <span class="uk-text-muted">(from GET ${esc(prefix + sample.from)})</span></label>
          <select class="uk-select" id="try-row"><option value="">—</option>
            ${sample.rows.map((r, i) => `<option value="${i}">${esc(label(r))}</option>`).join("")}</select></div>` : ""}
      </div>
      <div class="sa-form">
        ${params.map((p) => {
          const values = [...new Set(sample.rows.map((r) => valueFor(r, p)).filter((v) => v !== undefined && v !== null))];
          return `<div class="sa-field"><label class="uk-form-label" for="try-${esc(p)}">$${esc(p)}</label>
            <input class="uk-input" id="try-${esc(p)}" name="${esc(p)}" required list="try-${esc(p)}-values"
              placeholder="${values.length ? `e.g. ${esc(values[0])}` : ""}">
            <datalist id="try-${esc(p)}-values">${values.map((v) => `<option value="${esc(v)}">`).join("")}</datalist></div>`;
        }).join("")}
        ${e.method === "GET" ? `<div class="sa-field"><label class="uk-form-label" for="try-query">Query string</label>
          <input class="uk-input" id="try-query" name="__query" placeholder="_sort=name&_limit=5"></div>` : ""}
      </div>
      ${bodyParams.length ? `<div class="sa-field"><label class="uk-form-label" for="try-body">Body (JSON)</label>
        <textarea class="uk-textarea sa-code" id="try-body" name="__body">${esc(JSON.stringify(Object.fromEntries(bodyParams.map((p) => [p, ""])), null, 2))}</textarea></div>` : ""}
      <div class="sa-toolbar">
        <button class="uk-button uk-button-primary" type="submit">Send ${esc(e.method)}</button>
      </div>
    </form>
    <div id="try-result"></div>`;

  const form = main.querySelector("#try-form");
  form.querySelector("#try-user").addEventListener("change", async (event) => {
    const id = event.target.value;
    if (!id) {
      session.set(null);
      return;
    }
    const u = users.users.find((x) => String(x.id) === id);
    const s = await attempt(() => api(`/users/${encodeURIComponent(id)}/session`, "POST"));
    if (s) session.set({ token: s.sessionToken, label: u.identifier, id: u.id });
  });
  form.querySelector("#try-row")?.addEventListener("change", (event) => {
    const row = sample.rows[Number(event.target.value)];
    if (!row) return;
    for (const p of params) {
      const v = valueFor(row, p);
      if (v !== undefined && v !== null) form.querySelector(`#try-${CSS.escape(p)}`).value = v;
    }
    const bodyField = form.querySelector("#try-body");
    if (bodyField) {
      // The API never sends the password: it is left out (with it empty, a PUT would change it)
      const values = Object.fromEntries(bodyParams.filter((p) => p.toLowerCase() !== pwd).map((p) => [p, valueFor(row, p) ?? ""]));
      bodyField.value = JSON.stringify(values, null, 2);
    }
  });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const v = Object.fromEntries(new FormData(form));
    let path = e.route;
    for (const [k, value] of Object.entries(v)) {
      if (!k.startsWith("__")) path = path.replace("$" + k, encodeURIComponent(value));
    }
    if (v.__query) path += "?" + v.__query.replace(/^\?/, "");
    let reqBody;
    if (v.__body?.trim()) {
      try {
        reqBody = JSON.parse(v.__body);
      } catch {
        toast("The body is not valid JSON", "error");
        return;
      }
    }
    const res = await attempt(() => callApi(prefix, e.method, path, reqBody, { href: link("endpoints", "try", e.file, e.name) }));
    if (!res) return;
    main.querySelector("#try-result").innerHTML = `
      <p><span class="sa-status ${statusClass(res.status)}">${res.status}</span>
        <span class="uk-text-muted">${esc(e.method)} ${esc(prefix + path)} · ${res.ms} ms
        ${Array.isArray(res.data) ? ` · ${res.data.length} rows` : ""}</span></p>
      <pre class="sa-pre">${json(res.data)}</pre>`;
  });
}

/** Leaving the page: the lists of roles that UIkit moved to the body go too */
export function leave() {
  rolesClosed = null;
  document.querySelectorAll("body > .sa-roles__drop").forEach((d) => d.remove());
}
